class RivinaMicProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.ratio = Math.max(1, Math.round(sampleRate / 16000));
    this.queued = [];
  }
  process(inputs) {
    const input = inputs[0] && inputs[0][0];
    if (input) {
      for (let i = 0; i < input.length; i += this.ratio) {
        const s = Math.max(-1, Math.min(1, input[i]));
        this.queued.push(s < 0 ? s * 0x8000 : s * 0x7fff);
      }
      if (this.queued.length >= 1600) {
        this.port.postMessage(new Int16Array(this.queued));
        this.queued = [];
      }
    }
    return true;
  }
}
